PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?point ?ptype ?tsref ?tsid WHERE {
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?label }
  ?zone brick:hasPoint ?point .
  ?point a ?ptype .
  OPTIONAL { ?point ref:hasExternalReference ?tsref }
  OPTIONAL { ?tsref ref:hasTimeseriesId ?tsid }
  FILTER( CONTAINS(STR(?zone),"Core") || CONTAINS(STR(?label),"Core") || CONTAINS(STR(?zone),"_Z01") )
}

